CREATE OR REPLACE FUNCTION public.srk_worker_complete_assignment(
 p_booking_worker_id uuid,p_note text DEFAULT NULL
) RETURNS public.srk_booking_workers
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_assignment public.srk_booking_workers%rowtype;
 v_booking public.service_bookings%rowtype;
 v_booking_id uuid;
 v_total_seconds bigint;
 v_remaining integer;
 v_completion_note text:=nullif(btrim(p_note),'');
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 select bw.booking_id into v_booking_id
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_booking_worker_id and wp.user_id=auth.uid();
 if not found then raise exception 'Assignment not found or not yours'; end if;

 select * into v_booking from public.service_bookings where id=v_booking_id for update;
 if not found then raise exception 'Booking not found'; end if;

 select bw.* into v_assignment
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_booking_worker_id and wp.user_id=auth.uid()
 for update of bw;
 if not found then raise exception 'Assignment not found or not yours'; end if;
 if v_assignment.assignment_status not in ('accepted','assigned','working','paused') then
  raise exception 'Assignment is not active and cannot be completed';
 end if;
 if v_booking.status<>'in_progress' or v_booking.work_start_approval_status<>'approved' then
  raise exception 'Customer must approve work start before the worker can complete the booking';
 end if;

 if v_booking.pricing_unit_snapshot in ('per_item','motor_hp') then
  if v_completion_note is null or length(v_completion_note) not between 5 and 1000 then
   raise exception 'For fixed-price work, enter a completion note of 5 to 1000 characters';
  end if;
  if exists(select 1 from public.srk_worker_work_sessions
   where booking_worker_id=p_booking_worker_id and session_status in ('running','paused')) then
   raise exception 'Fixed-price work must not have a running timer session';
  end if;
  update public.srk_booking_workers
  set assignment_status='completed',released_at=clock_timestamp(),
      worker_completed_at=clock_timestamp(),worker_completion_note=v_completion_note,
      updated_at=clock_timestamp()
  where id=p_booking_worker_id returning * into v_assignment;
 else
  if not exists(select 1 from public.srk_worker_work_sessions where booking_worker_id=p_booking_worker_id) then
   raise exception 'At least one work session is required';
  end if;
  if exists(select 1 from public.srk_worker_work_sessions
   where booking_worker_id=p_booking_worker_id and session_status not in ('completed','cancelled')) then
   raise exception 'Complete or cancel every daily work session first';
  end if;
  select coalesce(sum(billable_seconds),0) into v_total_seconds
  from public.srk_worker_work_sessions where booking_worker_id=p_booking_worker_id;
  if v_total_seconds<=0 then
   raise exception 'No billable work time recorded; Admin must release this assignment or arrange more work';
  end if;
  update public.srk_booking_workers
  set assignment_status='completed',released_at=clock_timestamp(),
      worker_completed_at=clock_timestamp(),worker_completion_note=v_completion_note,
      updated_at=clock_timestamp()
  where id=p_booking_worker_id returning * into v_assignment;
 end if;

 select count(*) into v_remaining from public.srk_booking_workers
 where booking_id=v_assignment.booking_id
  and assignment_status not in ('completed','released','cancelled','rejected');
 if v_remaining=0 then
  update public.service_bookings
  set completion_approval_status='pending',completion_requested_at=clock_timestamp(),
      work_timer_running=false
  where id=v_booking.id and status='in_progress';
 end if;
 return v_assignment;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_worker_open_work_session(
 p_booking_worker_id uuid,p_work_date date DEFAULT ((now() AT TIME ZONE 'Asia/Kolkata'))::date
) RETURNS public.srk_worker_work_sessions
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_session public.srk_worker_work_sessions%rowtype;
 v_pricing_unit text;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if p_work_date<>(now() at time zone 'Asia/Kolkata')::date then
  raise exception 'Live timer session must use current India date; use offline sync for past events';
 end if;
 select b.pricing_unit_snapshot into v_pricing_unit
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 join public.service_bookings b on b.id=bw.booking_id
 where bw.id=p_booking_worker_id and wp.user_id=auth.uid()
  and bw.assignment_status in ('accepted','assigned','working','paused');
 if not found then raise exception 'You do not have an accepted assignment'; end if;
 if v_pricing_unit in ('per_item','motor_hp') then
  raise exception 'This fixed-price booking has no work timer; use fixed-price completion';
 end if;
 select * into v_session from public.srk_worker_work_sessions
 where booking_worker_id=p_booking_worker_id and work_date=p_work_date
  and session_status in ('not_started','running','paused')
 order by created_at desc limit 1;
 if found then return v_session; end if;
 insert into public.srk_worker_work_sessions(booking_worker_id,work_date)
 values(p_booking_worker_id,p_work_date) returning * into v_session;
 return v_session;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_guard_fixed_price_timer_disabled()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'pg_catalog','public'
AS $function$
declare v_pricing_unit text;
begin
 select b.pricing_unit_snapshot into v_pricing_unit
 from public.srk_booking_workers bw
 join public.service_bookings b on b.id=bw.booking_id
 where bw.id=new.booking_worker_id;
 if v_pricing_unit in ('per_item','motor_hp')
  and new.session_status in ('running','paused') then
  raise exception 'Timer is disabled for fixed-price bookings';
 end if;
 return new;
end
$function$;

DROP TRIGGER IF EXISTS srk_guard_fixed_price_timer_disabled
ON public.srk_worker_work_sessions;
CREATE TRIGGER srk_guard_fixed_price_timer_disabled
BEFORE INSERT OR UPDATE OF session_status,booking_worker_id
ON public.srk_worker_work_sessions
FOR EACH ROW
EXECUTE FUNCTION public.srk_guard_fixed_price_timer_disabled();

CREATE OR REPLACE FUNCTION public.srk_guard_worker_session()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'pg_catalog','public'
AS $function$
declare
 v_worker_id uuid;
 v_booking_id uuid;
 v_pricing_unit text;
 v_booking_status text;
 v_work_start_approval text;
begin
 select bw.worker_id,bw.booking_id,b.pricing_unit_snapshot,b.status,b.work_start_approval_status
 into v_worker_id,v_booking_id,v_pricing_unit,v_booking_status,v_work_start_approval
 from public.srk_booking_workers bw
 join public.service_bookings b on b.id=bw.booking_id
 where bw.id=new.booking_worker_id;
 if v_worker_id is null then raise exception 'Booking worker assignment not found'; end if;
 perform pg_advisory_xact_lock(hashtextextended(v_worker_id::text,0));
 if new.session_status in ('running','paused') then
  if v_pricing_unit in ('per_item','motor_hp') then
   raise exception 'Timer is disabled for fixed-price bookings';
  end if;
  if v_booking_status<>'in_progress' or v_work_start_approval<>'approved' then
   raise exception 'Customer work-start approval is required before starting the timer';
  end if;
  if exists(
   select 1 from public.srk_worker_work_sessions s
   where s.worker_id=v_worker_id and s.session_status in ('running','paused')
    and s.id<>coalesce(new.id,'00000000-0000-0000-0000-000000000000'::uuid)
  ) then
   raise exception 'Worker already has an active or paused work session at another booking';
  end if;
 end if;
 return new;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_worker_request_work_start_approval(
 p_booking_worker_id uuid
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_booking_id uuid;
 v_worker_id uuid;
 v_booking public.service_bookings%rowtype;
 v_assignment public.srk_booking_workers%rowtype;
 v_tech_count integer;
 v_helper_count integer;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 select bw.booking_id,bw.worker_id into v_booking_id,v_worker_id
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_booking_worker_id and wp.user_id=auth.uid();
 if not found then raise exception 'Assignment not found or not yours' using errcode='42501'; end if;

 select * into v_booking from public.service_bookings where id=v_booking_id for update;
 if not found then raise exception 'Booking not found'; end if;
 select * into v_assignment from public.srk_booking_workers
 where id=p_booking_worker_id for update;
 if not found or v_assignment.assignment_status not in ('accepted','assigned') then
  raise exception 'Only an accepted or assigned worker can request work-start approval';
 end if;
 if v_booking.status not in ('new','confirmed','assigned') then
  raise exception 'Booking is not ready for work-start approval';
 end if;
 if v_booking.work_start_approval_status in ('pending','approved') then
  raise exception 'Work-start approval is already pending or granted';
 end if;

 select count(*) filter(where worker_role='technician'
  and assignment_status in ('accepted','assigned')),
        count(*) filter(where worker_role='helper'
  and assignment_status in ('accepted','assigned'))
 into v_tech_count,v_helper_count
 from public.srk_booking_workers where booking_id=v_booking_id;
 if v_tech_count<coalesce(v_booking.requested_technician_count,0)
  or v_helper_count<coalesce(v_booking.requested_helper_count,0) then
  raise exception 'All requested Technician and Helper positions must be assigned before work starts';
 end if;
 if exists(
  select 1 from public.srk_booking_workers bw
  where bw.booking_id=v_booking_id and bw.assignment_status in ('accepted','assigned')
   and not exists(select 1 from public.srk_worker_schedule_blocks sb
    where sb.booking_worker_id=bw.id and sb.block_status in ('confirmed','in_progress'))
 ) then
  raise exception 'Every assigned worker must have a customer-confirmed schedule before work starts';
 end if;

 update public.service_bookings
 set status='awaiting_work_start_approval',
  work_start_approval_status='pending',
  work_start_requested_at=clock_timestamp(),
  work_timer_running=false
 where id=v_booking_id;

 insert into public.srk_app_notifications(
  user_id,notification_type,title,body,related_booking_id
 ) values(
  v_booking.customer_user_id,'work_start_request','Work start approval required',
  'Your assigned service team is ready to begin. Please approve or reject the work start.',
  v_booking_id
 );
 return jsonb_build_object('success',true,'status','awaiting_work_start_approval');
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_customer_respond_work_start(
 p_booking_id uuid,p_response text
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_booking public.service_bookings%rowtype;
 v_multi_worker boolean;
 v_timer_enabled boolean;
 v_next_status text;
begin
 if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if p_response is null or p_response not in ('approved','rejected') then
  raise exception 'Invalid response';
 end if;
 select * into v_booking from public.service_bookings
 where id=p_booking_id and customer_user_id=auth.uid() for update;
 if not found then raise exception 'Customer booking not found' using errcode='42501'; end if;
 if v_booking.status<>'awaiting_work_start_approval'
  or v_booking.work_start_approval_status<>'pending' then
  raise exception 'No work-start request is waiting for approval';
 end if;
 select exists(select 1 from public.srk_booking_workers where booking_id=p_booking_id)
 into v_multi_worker;
 v_timer_enabled:=v_booking.pricing_unit_snapshot not in ('per_item','motor_hp');
 v_next_status:=case when p_response='approved' then 'in_progress'
  when v_multi_worker then 'confirmed' else 'quote_approved' end;

 if p_response='approved' then
  insert into srk_private.work_transition_authorizations(transaction_id,booking_id,target_status)
  values(pg_catalog.txid_current(),p_booking_id,'in_progress');
 end if;

 update public.service_bookings set
  work_start_approval_status=p_response,
  status=v_next_status,
  work_started_at=case when p_response='approved' then pg_catalog.now() else null end,
  work_timer_running=(p_response='approved' and v_timer_enabled),
  work_timer_seconds=case when p_response='approved' and v_timer_enabled then 0 else work_timer_seconds end
 where id=p_booking_id;

 if p_response='approved' then
  delete from srk_private.work_transition_authorizations
  where transaction_id=pg_catalog.txid_current() and booking_id=p_booking_id
   and target_status='in_progress';
 end if;

 insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id)
 select wp.user_id,'work_start_response',
  case when p_response='approved' then 'Customer approved work start' else 'Customer rejected work start' end,
  case when p_response='approved' then 'Customer approved the work start. You may begin the job.'
   else 'Customer rejected the work-start request. Contact the customer and arrange another start time.' end,
  p_booking_id
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.booking_id=p_booking_id and bw.assignment_status in ('accepted','assigned');

 return pg_catalog.jsonb_build_object(
  'success',true,'response',p_response,'status',v_next_status,
  'timer_enabled',v_timer_enabled
 );
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_worker_complete_assignment(
 p_booking_worker_id uuid,p_note text DEFAULT NULL
) RETURNS public.srk_booking_workers
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_assignment public.srk_booking_workers%rowtype;
 v_booking public.service_bookings%rowtype;
 v_booking_id uuid;
 v_total_seconds bigint;
 v_remaining integer;
 v_completion_note text:=nullif(btrim(p_note),'');
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 select bw.booking_id into v_booking_id
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_booking_worker_id and wp.user_id=auth.uid();
 if not found then raise exception 'Assignment not found or not yours'; end if;

 select * into v_booking from public.service_bookings where id=v_booking_id for update;
 if not found then raise exception 'Booking not found'; end if;
 select bw.* into v_assignment
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_booking_worker_id and wp.user_id=auth.uid()
 for update of bw;
 if not found or v_assignment.assignment_status not in ('accepted','assigned','working','paused') then
  raise exception 'Assignment is not active and cannot be completed';
 end if;
 if v_booking.status<>'in_progress' then raise exception 'Booking is not in progress'; end if;

 if v_booking.pricing_unit_snapshot in ('per_item','motor_hp') then
  if v_booking.work_start_approval_status<>'approved' then
   raise exception 'Customer must approve the fixed-price work start before completion';
  end if;
  if v_completion_note is null or length(v_completion_note) not between 5 and 1000 then
   raise exception 'For fixed-price work, enter a completion note of 5 to 1000 characters';
  end if;
  if exists(select 1 from public.srk_worker_work_sessions
   where booking_worker_id=p_booking_worker_id and session_status in ('running','paused')) then
   raise exception 'Fixed-price work must not have a running timer session';
  end if;
  update public.srk_booking_workers
  set assignment_status='completed',released_at=clock_timestamp(),
      worker_completed_at=clock_timestamp(),worker_completion_note=v_completion_note,
      updated_at=clock_timestamp()
  where id=p_booking_worker_id returning * into v_assignment;
 else
  if not exists(select 1 from public.srk_worker_work_sessions where booking_worker_id=p_booking_worker_id) then
   raise exception 'At least one work session is required';
  end if;
  if exists(select 1 from public.srk_worker_work_sessions
   where booking_worker_id=p_booking_worker_id and session_status not in ('completed','cancelled')) then
   raise exception 'Complete or cancel every daily work session first';
  end if;
  select coalesce(sum(billable_seconds),0) into v_total_seconds
  from public.srk_worker_work_sessions where booking_worker_id=p_booking_worker_id;
  if v_total_seconds<=0 then
   raise exception 'No billable work time recorded; Admin must release this assignment or arrange more work';
  end if;
  update public.srk_booking_workers
  set assignment_status='completed',released_at=clock_timestamp(),
      worker_completed_at=clock_timestamp(),worker_completion_note=v_completion_note,
      updated_at=clock_timestamp()
  where id=p_booking_worker_id returning * into v_assignment;
 end if;

 update public.srk_worker_schedule_blocks
 set block_status='completed',updated_at=clock_timestamp()
 where booking_worker_id=p_booking_worker_id
  and block_status in ('reserved','confirmed','in_progress');

 select count(*) into v_remaining from public.srk_booking_workers
 where booking_id=v_assignment.booking_id
  and assignment_status not in ('completed','released','cancelled','rejected');
 if v_remaining=0 then
  update public.service_bookings
  set completion_approval_status='pending',completion_requested_at=clock_timestamp(),
      work_timer_running=false
  where id=v_booking.id and status='in_progress';
 end if;
 return v_assignment;
end
$function$;

